using ProjetoIntegradorBack.Domain.Entities; using ProjetoIntegradorBack.Domain.Enums; using ProjetoIntegradorBack.Domain.Interfaces; using ProjetoIntegradorBack.Infrastructure.Context; using ProjetoIntegradorBack.Shared.Pattern; using Microsoft.EntityFrameworkCore;
namespace ProjetoIntegradorBack.Infrastructure.Repositories;
public class AgendamentoRepository(ProjetoIntegradorBackDbContext context):IAgendamentoRepository{
public async Task<Result<Agendamento>> ObterPorIdAsync(Guid id,CancellationToken ct=default){try{var e=await context.Agendamentos.Include(x=>x.Cliente).Include(x=>x.Estabelecimento).Include(x=>x.Funcionario).Include(x=>x.Servico).FirstOrDefaultAsync(x=>x.Id==id,ct);return e==null?Result<Agendamento>.AsFailure(new Failure(404,"Agendamento não encontrado.")):Result<Agendamento>.AsSuccess(e);}catch(Exception ex){return Result<Agendamento>.AsFailure(new Failure(500,ex.Message));}}
public async Task<Result<IReadOnlyList<Agendamento>>> ObterPorClienteAsync(Guid id,StatusAgendamento? status,int pagina,int tamanho,CancellationToken ct=default){try{var q=context.Agendamentos.Where(x=>x.ClienteId==id);if(status.HasValue)q=q.Where(x=>x.Status==status);return Result<IReadOnlyList<Agendamento>>.AsSuccess(await q.OrderByDescending(x=>x.DataHora).Skip((pagina-1)*tamanho).Take(tamanho).ToListAsync(ct));}catch(Exception ex){return Result<IReadOnlyList<Agendamento>>.AsFailure(new Failure(500,ex.Message));}}
public async Task<Result<int>> ContarPorClienteAsync(Guid id,StatusAgendamento? status,CancellationToken ct=default){try{var q=context.Agendamentos.Where(x=>x.ClienteId==id);if(status.HasValue)q=q.Where(x=>x.Status==status);return Result<int>.AsSuccess(await q.CountAsync(ct));}catch(Exception ex){return Result<int>.AsFailure(new Failure(500,ex.Message));}}
public Task<Result<IReadOnlyList<Agendamento>>> ObterPorFuncionarioNoMesAsync(Guid id,int ano,int mes,CancellationToken ct=default)=>Periodo(id,x=>x.DataHora.Year==ano&&x.DataHora.Month==mes,ct);
public async Task<Result<IReadOnlyList<Agendamento>>> ObterPorFuncionarioNoDiaAsync(Guid id,DateOnly dia,CancellationToken ct=default){var ini=dia.ToDateTime(TimeOnly.MinValue);var fim=dia.ToDateTime(TimeOnly.MaxValue);return await Periodo(id,x=>x.DataHora>=ini&&x.DataHora<=fim,ct);}
private async Task<Result<IReadOnlyList<Agendamento>>> Periodo(Guid id,System.Linq.Expressions.Expression<Func<Agendamento,bool>> p,CancellationToken ct){try{return Result<IReadOnlyList<Agendamento>>.AsSuccess(await context.Agendamentos.Where(x=>x.FuncionarioId==id).Where(p).OrderBy(x=>x.DataHora).ToListAsync(ct));}catch(Exception ex){return Result<IReadOnlyList<Agendamento>>.AsFailure(new Failure(500,ex.Message));}}
public async Task<Result<Agendamento>> AdicionarAsync(Agendamento e,CancellationToken ct=default){try{e.Id=Guid.NewGuid();e.CriadoEm=DateTime.UtcNow;e.NumeroReserva=$"BT-{DateTime.UtcNow:yyyyMMdd}-{Guid.NewGuid().ToString()[..6].ToUpper()}";await context.Agendamentos.AddAsync(e,ct);await context.SaveChangesAsync(ct);return Result<Agendamento>.AsSuccess(e);}catch(Exception ex){return Result<Agendamento>.AsFailure(new Failure(500,ex.Message));}}
public async Task<Result<Agendamento>> AtualizarAsync(Agendamento e,CancellationToken ct=default){try{e.AtualizadoEm=DateTime.UtcNow;context.Agendamentos.Update(e);await context.SaveChangesAsync(ct);return Result<Agendamento>.AsSuccess(e);}catch(Exception ex){return Result<Agendamento>.AsFailure(new Failure(500,ex.Message));}}
public async Task<Result<bool>> ExisteConflitoDeHorarioAsync(Guid id,DateTime dataHora,int duracaoMin,CancellationToken ct=default){try{var fim=dataHora.AddMinutes(duracaoMin);return Result<bool>.AsSuccess(await context.Agendamentos.Include(x=>x.Servico).Where(x=>x.FuncionarioId==id&&x.Status!=StatusAgendamento.Cancelado).AnyAsync(x=>dataHora<x.DataHora.AddMinutes(x.Servico.DuracaoMinutos)&&fim>x.DataHora,ct));}catch(Exception ex){return Result<bool>.AsFailure(new Failure(500,ex.Message));}}
public async Task<Result<IReadOnlyList<Agendamento>>> ObterPorEstabelecimentoNoPeriodoAsync(Guid id,DateTime inicio,DateTime fim,CancellationToken ct=default){try{return Result<IReadOnlyList<Agendamento>>.AsSuccess(await context.Agendamentos.Where(x=>x.EstabelecimentoId==id&&x.DataHora>=inicio&&x.DataHora<=fim).ToListAsync(ct));}catch(Exception ex){return Result<IReadOnlyList<Agendamento>>.AsFailure(new Failure(500,ex.Message));}}}